#!/usr/bin/env python3
# tools/titan/results/wave55-plan/regen.selfcheck-rg.py — appends §RG to probes-selfcheck.txt for the pre-landing regeneration
# (regen.done.md; PLAN §10 item 5). The sections above §RG were generated by fix-r6 from expectations 8fbfc83a; the regeneration
# changed L5's probe, L5's residual declaration and L5's standing replays only. §RG holds a NARROWED re-run on the regenerated
# bytes — `probes-selfcheck.py --teeth-lanes L5 --out <scratch>` from the SHARED tree (§0 all lanes, §R, §L1–§L7, §C4, and §T /
# §T3 / §T4 / §T5 for L5) — and proves the rest stands: every line of §0, §R and §L1–§L4 / §L6 / §L7 of the re-run equals the
# installed record's (only §L5's [K] ios zone list and the header differ), and every other lane's probe / gate / teeth file is
# byte-identical to the one the sections above ran. Written atomically (temp beside it + os.replace); refuses a second append.
# Usage: python3 regen.selfcheck-rg.py <narrowed re-run .txt> <regen.l5-proof.out.txt> <the fix-r6 record's sha256 prefix>
import hashlib, os, re, sys
HERE = os.path.dirname(os.path.abspath(__file__))
REC = os.path.join(HERE, 'probes-selfcheck.txt')
new_p, proof_p, rec_sha = sys.argv[1:4]
old, new = open(REC).read(), open(new_p).read()
assert hashlib.sha256(old.encode()).hexdigest().startswith(rec_sha), 'probes-selfcheck.txt is not the fix-r6 record'
assert '\n## §RG ' not in old, 'refused: §RG is already appended'
sec = lambda t, name: (re.search(r'^## ' + re.escape(name) + r'.*?(?=^## )', t, re.S | re.M) or [''])[0]
def body(t, name):
    return sec(t, name)
SAME = ['§0 ', '§R ', '§L1 ', '§L2 ', '§L3 ', '§L4 ', '§L6 ', '§L7 ']
ident = {n.strip(): body(old, n) == body(new, n) and body(old, n) != '' for n in SAME}
assert all(ident.values()), ident
ol, nl = body(old, '§L5 ').splitlines(), body(new, '§L5 ').splitlines()
d5 = [(a, b) for a, b in zip(ol, nl) if a != b]
assert len(ol) == len(nl) and all('[K] counter-suffix ios zones' in a and '[K] counter-suffix ios zones' in b for a, b in d5), d5[:2]
v = lambda l: l.rsplit(' → ', 1)[1].split(' (')[0] if ' → ' in l else ''
assert all(v(a) == v(b) for a, b in d5), 'a §L5 verdict changed'
sha = lambda f: hashlib.sha256(open(os.path.join(HERE, f), 'rb').read()).hexdigest()[:16]
OTHER = ['hyphen-ios-linebox.geometry.py', 'compose-wpt-content-box-cb.geometry.py', 'cbb-android.geometry.py', 'positioned-parent-slot.geometry.py',
         'ua-heading-margin.geometry.py', 'android-paint-order.geometry.py', 'flex-zero-gap-rules.geometry.py', 'geometry-gate.py', 'probes-selfcheck.py',
         'probes-teeth.py', 'probes-teeth-r2.py', 'probes-teeth-r3.py', 'probes-teeth-r4.py', 'probes-teeth-r5.py', 'fix-r6.zones.py']
proof = open(proof_p).read()
assert proof.rstrip().endswith('violations: 0'), 'regen.l5-proof did not hold'
hdr = new.splitlines()[:3]
out = ['', '## §RG the pre-landing regeneration (regen.done.md; PLAN §10 item 5, D41): the L5 probe edit, the residual declaration and the re-grafted replays, re-proven',
       f'# the narrowed re-run: probes-selfcheck.py --teeth-lanes L5, from the shared tree; its header: {hdr[1].lstrip("# ")} / {hdr[2].lstrip("# ")}',
       '# L5 bytes now: counter-suffix-rows.geometry.py ' + sha('counter-suffix-rows.geometry.py') + '… · residual-read.py ' + sha('residual-read.py') + '… · expectations.json ' + sha('expectations.json') + '…',
       '# unchanged since the sections above (sha256, first 16): ' + ' · '.join(f'{f} {sha(f)}' for f in OTHER),
       f'# re-run vs the sections above: §0, §R, §L1–§L4, §L6, §L7 line-for-line IDENTICAL ({", ".join(k for k, x in ident.items() if x)}); '
       f'§L5 differs on {len(d5)} line(s), each the [K] counter-suffix ios zone list (U3-ios\'s five run boxes carved out: R1), every verdict equal',
       '']
for name in ('§C4 ', '§T ', '§T3 ', '§T4 ', '§T5 '):
    b = body(new, name).rstrip('\n').splitlines()
    out += [('### (re-run) ' + b[0][3:]) if b else f'### (re-run) {name}: MISSING'] + b[1:] + ['']
tail = new[new.index('## Every GATING key'):].splitlines()
out += ['### (re-run) the L5 rows of the per-key table, and its summary line (§T / §T3 / §T4 / §T5 counts are L5\'s: --teeth-lanes L5)']
out += [l for l in tail if 'L5-counter-suffix-rows' in l] + [l for l in tail if l.startswith('gating keys ')] + ['']
out += ['### regen.l5-proof.out.txt (summary): ' + ' · '.join(l.strip() for l in proof.splitlines() if l.startswith('  → ') or l.startswith('violations'))[:2000], '']
tmp = REC + '.tmp-regen'
open(tmp, 'w').write(old.rstrip('\n') + '\n' + '\n'.join(out) + '\n'); os.replace(tmp, REC)
print(f'appended §RG ({len(out)} lines); probes-selfcheck.txt sha256 {hashlib.sha256(open(REC, "rb").read()).hexdigest()}')
